INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Managed IT Services immer teurer als interne IT sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann kosteneffizienter sein"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Managed IT Services für eine Firma auswähle?', 3, '[{"text": "Service Level Agreement", "correct": true, "because": "Definiert Leistung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Firmendesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein Managed Service Provider typischerweise?', 5, '[{"text": "Netzwerküberwachung", "correct": true, "because": "Sichert Betrieb"}, {"text": "Sicherheitsmanagement", "correct": true, "because": "Schützt Daten"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein IT-Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Managed IT Services entlasten interne IT. b) Sie ersetzen immer die interne IT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Managed IT Services für ein Netzwerk einrichte?', 4, '[{"text": "SLA-Details", "correct": false, "because": "Definieren Leistung"}, {"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen System"}, {"text": "Büroausstattung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Managed IT Services immer lokal bereitgestellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch remote möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Managed IT Services?', 3, '[{"text": "IT-Entlastung", "correct": true, "because": "Fokus auf Kerngeschäft"}, {"text": "Schnellste Installation", "correct": false, "because": "Sekundär"}, {"text": "Weniger Technik", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Managed IT Services?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Reduziert interne Kosten"}, {"text": "Expertenzugriff", "correct": true, "because": "Fachwissen extern"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Managed IT Services verbessern Sicherheit. b) Sie sind immer teurer als Inhouse-IT. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich Managed IT Services für ein Unternehmen plane?', 4, '[{"text": "Servicevertrag", "correct": false, "because": "Definiert Leistung"}, {"text": "Sicherheitskonzept", "correct": false, "because": "Schützt Daten"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Managed IT Services immer für große Firmen gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Managed IT Services?', 4, '[{"text": "Abhängigkeit vom Anbieter", "correct": true, "because": "Verlust an Kontrolle"}, {"text": "Vertragsbindung", "correct": true, "because": "Einschränkt Flexibilität"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Managed IT Services nur Cloud-Dienste umfassen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Dienste möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Managed IT Services für Netzwerksicherheit auszuwählen?', 3, '[{"text": "Sicherheitskompetenz", "correct": true, "because": "Schützt Netzwerk"}, {"text": "Günstigster Preis", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Managed IT Services bieten 24/7 Support. b) Sie sind immer vor Ort.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft remote"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Managed IT Services?', 5, '[{"text": "SLA-Qualität", "correct": true, "because": "Definiert Leistung"}, {"text": "Anbieterkompetenz", "correct": true, "because": "Sichert Expertise"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Managed IT Services für eine Firma plane?', 3, '[{"text": "Supportumfang", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Vertragslaufzeit", "correct": false, "because": "Beeinflusst Bindung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Managed IT Services immer monatlich abgerechnet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch jährlich möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel abrechenbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Managed IT Services die interne IT komplett ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzung möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Managed IT Services?', 4, '[{"text": "Service Level Agreement", "correct": true, "because": "Definiert Leistung"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
